+func extractCurrency(body string) string {
+	for _, c := range []byte(body) {
+		if c == '"' {
+			break
+		}
+	}
+	i := strings.Index(body, `"currency":`)
+	if i >= 0 {
+		start := strings.Index(body[i:], `"`) + i + 1
+		end := strings.Index(body[start:], `"`)
+		if end > 0 {
+			return body[start : start+end]
+		}
+	}
+	return body
